#!/usr/bin/env python3
"""Writes THIRD_PARTY_LICENSES.txt, the licence texts that travel with the program.

It holds the texts of the fonts, of ONNX Runtime and of every crate linked into the Windows
build. The program shows it (Settings > Advanced) and the release zip carries it.

Needs cargo-about 0.9.3 (`cargo install cargo-about --version 0.9.3 --locked --features cli`)
and network access: about.toml takes some texts from the crates' repositories.
"""

import re
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUTPUT = ROOT / "THIRD_PARTY_LICENSES.txt"
# licenses/onnxruntime holds the texts of the ONNX Runtime build that this ort-sys downloads
# (its dist.tsv names ms@1.31.0). See licenses/onnxruntime/SOURCE.md.
ORT_SYS = "2.0.0-rc.15"
ORT_VERSION = "1.31.0"
FONTS = [
    ("Inter", "Inter-OFL.txt"),
    ("JetBrains Mono", "JetBrainsMono-OFL.txt"),
    ("Noto Sans Thai", "NotoSansThai-OFL.txt"),
]
MARK = "@@LICENCE@@ "
# What the standard MIT and BSD texts hold when nobody's name was filled in.
TEMPLATE_LINE = re.compile(r"<year>|<copyright holders?>|<owner>", re.IGNORECASE)


def read(path):
    return path.read_text(encoding="utf-8-sig").replace("\r\n", "\n").strip("\n")


def section(title, body):
    rule = "=" * 80
    return f"{rule}\n{title}\n{rule}\n\n{body}\n"


def check_onnx_runtime_pin():
    found = re.findall(r'name = "ort-sys"\nversion = "([^"]+)"', read(ROOT / "Cargo.lock"))
    if found != [ORT_SYS]:
        sys.exit(
            f"Cargo.lock has ort-sys {found}, but licenses/onnxruntime holds the texts for "
            f"ONNX Runtime {ORT_VERSION} of ort-sys {ORT_SYS}. Update the texts, then this script."
        )


def crate_sections():
    with tempfile.TemporaryDirectory() as tmp:
        out = Path(tmp) / "crates.txt"
        subprocess.run(
            ["cargo", "about", "generate", "--locked", "--fail", "--output-file", str(out), "about.hbs"],
            cwd=ROOT,
            check=True,
        )
        text = read(out)
    sections = []
    for part in text.split(MARK)[1:]:
        title, rest = part.split("\n", 1)
        users, licence = rest.split("\n\n", 1)
        users = sorted(line for line in users.split("\n") if line.startswith("- "))
        if [line.split()[1] for line in users] == ["meeting-recorder"]:
            continue  # the program itself: see LICENSE
        licence = licence.strip("\n")
        if TEMPLATE_LINE.search(licence):
            sys.exit(
                "No copyright holder for these crates; clarify them in about.toml:\n"
                + "\n".join(users)
            )
        sections.append((title, "\n".join(users), licence))
    if not sections:
        sys.exit("cargo-about returned no licences")
    # cargo-about's order is not promised; a stable one keeps the diff check honest.
    sections.sort()
    return [section(title, f"Used by:\n{users}\n\n{licence}") for title, users, licence in sections]


def main():
    check_onnx_runtime_pin()
    parts = [
        "Third-party licences\n\n"
        "The texts below belong to the fonts, ONNX Runtime and the Rust crates inside\n"
        "meeting-recorder.exe. THIRD_PARTY_NOTICES.md covers ported source code and the speech\n"
        "model. This file is generated by .github/scripts/third_party_licenses.py.\n"
    ]
    for name, licence in FONTS:
        parts.append(section(f"Font: {name} (SIL Open Font License 1.1)", read(ROOT / "assets" / "fonts" / licence)))
    ort = ROOT / "licenses" / "onnxruntime"
    parts.append(section(f"ONNX Runtime {ORT_VERSION} (MIT)", read(ort / "LICENSE")))
    parts.append(section(f"ONNX Runtime {ORT_VERSION}: its third-party notices", read(ort / "ThirdPartyNotices.txt")))
    parts.extend(crate_sections())
    OUTPUT.write_text("\n".join(parts), encoding="utf-8", newline="\n")
    print(f"wrote {OUTPUT.name}: {OUTPUT.stat().st_size} bytes")


if __name__ == "__main__":
    main()
